m_n = 3.2
feasible = []
for z1 in range(14, 26):
    z2 = 4*z1
    for beta_deg in [8, 10, 12, 14, 16, 18, 20]:
        beta = math.radians(beta_deg)
        cosb = math.cos(beta)
        d2 = m_n*z2/cosb
        da2 = d2 + 2*m_n
        housing_h = da2 + 20 + 16 + 20
        a = m_n*(z1+z2)/(2*cosb)
        z_min = 17*cosb**3
        if housing_h <= 300 and z1 >= z_min:
            feasible.append({
                'z1': z1, 'z2': z2, 'beta_deg': beta_deg,
                'a': round(a,1), 'd2': round(d2,1), 'da2': round(da2,1),
                'housing_h': round(housing_h,1), 'z_min': round(z_min,2)
            })
outputs = {'feasible_options': feasible[:12], 'count': len(feasible)}

